import {createGardenState,stepGarden} from '../../../../src/js/garden/GardenSimulation.js';
import {GARDEN_AERIAL as a,GARDEN_PLATFORM_BY_ID as map} from '../../../../src/js/garden/GardenLevel.js';
import {createPilot} from '../jardim-v2/piloto.mjs';
const s=createGardenState(),p=map.get(a.entry),pilot=createPilot();s.stage='RUNNING';Object.assign(s.player,{x:p.x+120,y:p.y,onGround:true,support:p.id,terrain:'soil'});s.safeGround=p.id;s.checkpoint=p.x+120;let previous=null;const last=[];
for(let tick=0;tick<7200&&s.stage==='RUNNING'&&s.player.x<a.end;tick++){
 const input=pilot(s);if(s.player.support!==previous){console.log('APOIO',JSON.stringify({t:s.time,x:s.player.x-a.x,y:s.player.y,support:s.player.support,vy:s.player.vy,air:s.player.airSpeed,held:s.jumpHeld,input}));previous=s.player.support;}
 if(s.player.x>a.x+2700)last.push({t:s.time,x:s.player.x-a.x,y:s.player.y,vx:s.player.vx,vy:s.player.vy,support:s.player.support,held:s.jumpHeld,input});if(last.length>20)last.shift();stepGarden(s,input,1/60);
}
console.log('RESULTADO',JSON.stringify({stage:s.stage,time:s.time,x:s.player.x-a.x,y:s.player.y}));if(s.stage!=='RUNNING'||s.player.x<a.end)console.log('ÚLTIMOS QUADROS',JSON.stringify(last));
